(function () {
  "use strict";
  var MASK_W = 720, MASK_H = 360, MASK_B64 = "";
  var PHI0 = 18 * Math.PI / 180, LAM0 = -8 * Math.PI / 180;
  var W = 384;
  var SPIN = 2 * Math.PI;
  var IDLE_RATE = (2 * Math.PI) / 42;
  var PLANET_DEG_PER_SEC = 14;
  var OCEAN_A = 0.14;

  var MASK = (function () {
    var bin = atob(MASK_B64), b = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) b[i] = bin.charCodeAt(i);
    return b;
  })();

  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  function ease(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
  function landBit(row, col) {
    var idx = row * MASK_W + col;
    return (MASK[idx >> 3] >> (7 - (idx & 7))) & 1;
  }

  function init(node) {
    var canvas = node.querySelector("canvas");
    if (!canvas) return;
    var ctx = canvas.getContext("2d");
    canvas.width = W; canvas.height = W;
    var sc = document.createElement("canvas");
    sc.width = W; sc.height = W;
    var sctx = sc.getContext("2d", { willReadFrequently: true });
    var src = new Uint8ClampedArray(W * W * 4);
    var out = ctx.createImageData(W, W);
    var od = out.data;
    var rhoA = new Float32Array(W * W);
    var kA = new Float32Array(W * W);
    var rowA = new Uint16Array(W * W);
    var colA = new Uint16Array(W * W);
    var base = new Uint8ClampedArray(W * W * 4);
    var ready = false, mode = "rest";
    var angle = 0, angle0 = 0;
    var t = 0, from = 0, to = 0, t0 = 0, dur = 1100, morphRaf = 0;
    var restRaf = 0, restLast = 0;
    var planetRaf = 0, planetLast = 0, planetSpin = 0, planetAcc = 0;
    var autoTimer = 0, visible = true, atm = null;
    var reduced = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    function precompute() {
      var cx = W / 2;
      for (var y = 0; y < W; y++) {
        for (var x = 0; x < W; x++) {
          var p = y * W + x;
          var dx = x + 0.5 - cx, dy = y + 0.5 - cx;
          var rho = Math.min(Math.sqrt(dx * dx + dy * dy) / cx, 1);
          rhoA[p] = rho;
          var rs = Math.sqrt(Math.max(0, 1 - Math.sqrt(Math.max(0, 1 - rho * rho))));
          kA[p] = rho > 1e-4 ? rs / rho : 0.7071;
          var th = Math.atan2(dy, dx);
          var z = 1 - rho * rho, s2 = Math.sqrt(2 - rho * rho), sinc = rho * s2;
          var u = Math.cos(th), v = -Math.sin(th);
          var phi = Math.asin(clamp(z * Math.sin(PHI0) + v * sinc * Math.cos(PHI0), -1, 1));
          var lam = LAM0 + Math.atan2(u * sinc, Math.cos(PHI0) * z - v * Math.sin(PHI0) * sinc);
          var lat = phi * 180 / Math.PI;
          var lon = ((lam * 180 / Math.PI + 180) % 360 + 360) % 360 - 180;
          var row = Math.floor((90 - lat) * 2);
          rowA[p] = row < 0 ? 0 : row > MASK_H - 1 ? MASK_H - 1 : row;
          var col = Math.floor((lon + 180) * 2);
          colA[p] = col < 0 ? 0 : col > MASK_W - 1 ? MASK_W - 1 : col;
        }
      }
    }

    function atmosphere(e) {
      if (e <= 0.001) return;
      var cx = W / 2;
      if (!atm) {
        atm = ctx.createRadialGradient(cx, cx, cx * 0.84, cx, cx, cx);
        atm.addColorStop(0, "rgba(130,180,230,0)");
        atm.addColorStop(1, "rgba(120,170,225,0.3)");
      }
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cx, cx, 0, Math.PI * 2);
      ctx.clip();
      ctx.globalAlpha = Math.min(1, e * 1.1);
      ctx.fillStyle = atm;
      ctx.fillRect(0, 0, W, W);
      ctx.globalAlpha = 1;
      ctx.restore();
    }

    function drawRosette(a) {
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, W, W);
      ctx.translate(W / 2, W / 2);
      ctx.rotate(a);
      ctx.translate(-W / 2, -W / 2);
      ctx.drawImage(sc, 0, 0, W, W);
      ctx.setTransform(1, 0, 0, 1, 0, 0);
    }

    function drawWarp(tt) {
      var cx = W / 2, e = ease(tt);
      var rot = -(angle0 + SPIN * e);
      var cr = Math.cos(rot), sr = Math.sin(rot);
      var warpCols = (planetSpin * 2) % MASK_W;
      var s = src, o = od;
      for (var y = 0; y < W; y++) {
        var dy = y + 0.5 - cx;
        for (var x = 0; x < W; x++) {
          var p = y * W + x, q = p * 4;
          var dx = x + 0.5 - cx;
          var k = 1 + (kA[p] - 1) * e;
          var sx = cx + (dx * cr - dy * sr) * k;
          var sy = cx + (dx * sr + dy * cr) * k;
          var x0 = sx - 0.5, y0 = sy - 0.5;
          var ix = Math.floor(x0), iy = Math.floor(y0);
          var fx = x0 - ix, fy = y0 - iy;
          var ix1 = ix + 1, iy1 = iy + 1;
          if (ix < 0) ix = 0; else if (ix > W - 1) ix = W - 1;
          if (iy < 0) iy = 0; else if (iy > W - 1) iy = W - 1;
          if (ix1 < 0) ix1 = 0; else if (ix1 > W - 1) ix1 = W - 1;
          if (iy1 < 0) iy1 = 0; else if (iy1 > W - 1) iy1 = W - 1;
          var i00 = (iy * W + ix) * 4, i10 = (iy * W + ix1) * 4, i01 = (iy1 * W + ix) * 4, i11 = (iy1 * W + ix1) * 4;
          var w00 = (1 - fx) * (1 - fy), w10 = fx * (1 - fy), w01 = (1 - fx) * fy, w11 = fx * fy;
          var a = s[i00 + 3] * w00 + s[i10 + 3] * w10 + s[i01 + 3] * w01 + s[i11 + 3] * w11;
          if (a < 1) { o[q] = 0; o[q + 1] = 0; o[q + 2] = 0; o[q + 3] = 0; base[q + 3] = 0; continue; }
          var inv = 255 / a;
          var r = (s[i00] * w00 + s[i10] * w10 + s[i01] * w01 + s[i11] * w11) * inv;
          var g = (s[i00 + 1] * w00 + s[i10 + 1] * w10 + s[i01 + 1] * w01 + s[i11 + 1] * w11) * inv;
          var b = (s[i00 + 2] * w00 + s[i10 + 2] * w10 + s[i01 + 2] * w01 + s[i11 + 2] * w11) * inv;
          var sh = 1 - 0.22 * rhoA[p] * e;
          r *= sh; g *= sh; b *= sh;
          base[q] = r; base[q + 1] = g; base[q + 2] = b; base[q + 3] = a;
          var col = colA[p] + warpCols;
          if (col >= MASK_W) col -= MASK_W;
          var land = landBit(rowA[p], col);
          o[q] = r; o[q + 1] = g; o[q + 2] = b;
          o[q + 3] = land ? a : a * (1 - (1 - OCEAN_A) * e);
        }
      }
      ctx.putImageData(out, 0, 0);
      atmosphere(e);
    }

    function drawPlanet() {
      var scols = (planetSpin * 2) % MASK_W;
      var o = od, bs = base;
      for (var p = 0; p < W * W; p++) {
        var q = p * 4;
        var a = bs[q + 3];
        if (a < 1) { o[q + 3] = 0; continue; }
        var col = colA[p] + scols;
        if (col >= MASK_W) col -= MASK_W;
        var land = landBit(rowA[p], col);
        o[q] = bs[q]; o[q + 1] = bs[q + 1]; o[q + 2] = bs[q + 2];
        o[q + 3] = land ? a : a * OCEAN_A;
      }
      ctx.putImageData(out, 0, 0);
      atmosphere(1);
    }

    function restLoop(now) {
      if (mode !== "rest") { restRaf = 0; return; }
      var dt = (now - restLast) / 1000; restLast = now;
      if (dt > 0.25) dt = 0.25;
      if (visible) { angle += IDLE_RATE * dt; drawRosette(angle); }
      restRaf = requestAnimationFrame(restLoop);
    }

    function morphTick(now) {
      var pr = clamp((now - t0) / dur, 0, 1);
      t = from + (to - from) * pr;
      if (visible) drawWarp(t);
      if (pr < 1) { morphRaf = requestAnimationFrame(morphTick); }
      else {
        morphRaf = 0;
        if (!visible) drawWarp(t);
        if (to === 1) { mode = "planet"; node.classList.add("is-planet"); startPlanet(); }
        else { mode = "rest"; node.classList.remove("is-planet"); angle = angle0; restLast = performance.now(); restRaf = requestAnimationFrame(restLoop); }
      }
    }

    function planetLoop(now) {
      if (mode !== "planet") { planetRaf = 0; return; }
      var dt = (now - planetLast) / 1000; planetLast = now;
      if (dt > 0.25) dt = 0.25;
      if (visible) {
        planetSpin = (planetSpin + PLANET_DEG_PER_SEC * dt) % 360;
        drawPlanet();
      }
      planetRaf = requestAnimationFrame(planetLoop);
    }

    function startPlanet() {
      if (reduced || planetRaf) return;
      planetLast = performance.now(); planetAcc = 1;
      planetRaf = requestAnimationFrame(planetLoop);
    }
    function stopLoops() {
      cancelAnimationFrame(morphRaf); morphRaf = 0;
      cancelAnimationFrame(restRaf); restRaf = 0;
      cancelAnimationFrame(planetRaf); planetRaf = 0;
    }

    function go(target, duration) {
      if (!ready) return;
      clearTimeout(autoTimer);
      stopLoops();
      if (target === 1) planetSpin = 0;
      node.setAttribute("aria-pressed", target === 1 ? "true" : "false");
      if (reduced) {
        t = target; mode = target === 1 ? "planet" : "rest";
        node.classList.toggle("is-planet", target === 1);
        if (target === 1) { angle0 = angle; drawWarp(1); } else { drawRosette(angle); }
        return;
      }
      from = t; to = target; t0 = performance.now(); dur = duration || 1100;
      angle0 = angle; mode = "morph";
      morphRaf = requestAnimationFrame(morphTick);
    }
    function toggle() {
      if (morphRaf) { go(to, 350); return; }
      if (mode === "planet") go(0, 1100);
      else go(1, 1100);
    }
    node.addEventListener("click", function (e) { e.preventDefault(); toggle(); });

    if (window.matchMedia) {
      var mq = window.matchMedia("(prefers-reduced-motion: reduce)");
      var onmq = function () {
        reduced = mq.matches;
        if (reduced) {
          stopLoops();
          if (mode === "morph") {
            t = to;
            if (to === 1) { angle0 = angle; drawWarp(1); mode = "planet"; node.classList.add("is-planet"); }
            else { mode = "rest"; node.classList.remove("is-planet"); drawRosette(angle); }
          }
        } else {
          if (mode === "rest" && !restRaf) { restLast = performance.now(); restRaf = requestAnimationFrame(restLoop); }
          if (mode === "planet" && !planetRaf) startPlanet();
        }
      };
      if (mq.addEventListener) mq.addEventListener("change", onmq);
      else if (mq.addListener) mq.addListener(onmq);
    }

    if ("IntersectionObserver" in window) {
      var io = new IntersectionObserver(function (es) { visible = es[0].isIntersecting; }, { threshold: 0 });
      io.observe(node);
    }

    var bitmap = new Image();
    bitmap.onload = function () {
      sctx.drawImage(bitmap, 0, 0, W, W);
      var id = sctx.getImageData(0, 0, W, W).data;
      for (var i = 0; i < id.length; i += 4) {
        var al = id[i + 3] / 255;
        src[i] = id[i] * al; src[i + 1] = id[i + 1] * al; src[i + 2] = id[i + 2] * al; src[i + 3] = id[i + 3];
      }
      bitmap = null;
      precompute();
      ready = true;
      drawRosette(0);
      node.classList.add("is-ready");
      node.setAttribute("aria-pressed", "false");
      if (reduced) { mode = "rest"; }
      else {
        if (!restRaf) { restLast = performance.now(); restRaf = requestAnimationFrame(restLoop); }
        autoTimer = setTimeout(function () { if (mode === "rest") { go(1, 4600); } }, 1500);
      }
    };
    bitmap.onerror = function () { bitmap = null; };
    bitmap.src = node.getAttribute("data-logo");
  }

  function boot() {
    var nodes = document.querySelectorAll(".logo-morph");
    for (var i = 0; i < nodes.length; i++) init(nodes[i]);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();
})();
